Problem:
A pharmaceutical manufacturing plant has 1000 mg of cornstarch to rush orders of diabetic pills and latex gloves. Each diabetic pill requires 4 mg of cornstarch and 0.2 minutes to manufacture. Each individual latex glove requires 7 mg of cornstarch and 0.15 minutes to manufacture. The pharmaceutical manufacturing plant needs to make at least 20 diabetic pills. Since latex gloves are important, at least 60% of produced items must be latex gloves. How many of each should the pharmaceutical manufacturing plant make to minimize the total number of minutes needed?

Model and facts:
{
 "model": {
  "variables": [
   {
    "name": "diabetic pills",
    "lower": 0.0,
    "upper": null,
    "integer": true
   },
   {
    "name": "latex gloves",
    "lower": 0.0,
    "upper": null,
    "integer": true
   }
  ],
  "objective": {
   "sense": "min",
   "terms": [
    {
     "var": "diabetic pills",
     "coef": 0.2
    },
    {
     "var": "latex gloves",
     "coef": 0.15
    }
   ]
  },
  "constraints": [
   {
    "name": "cornstarch",
    "terms": [
     {
      "var": "diabetic pills",
      "coef": 4.0
     },
     {
      "var": "latex gloves",
      "coef": 7.0
     }
    ],
    "sense": "<=",
    "rhs": 1000.0
   },
   {
    "name": "min_pills",
    "terms": [
     {
      "var": "diabetic pills",
      "coef": 1.0
     }
    ],
    "sense": ">=",
    "rhs": 20.0
   },
   {
    "name": "glove_share",
    "terms": [
     {
      "var": "diabetic pills",
      "coef": -0.6
     },
     {
      "var": "latex gloves",
      "coef": 0.4
     }
    ],
    "sense": ">=",
    "rhs": 0.0
   }
  ]
 },
 "facts": {
  "objective": 8.5,
  "values": {
   "diabetic pills": 20.0,
   "latex gloves": 30.0
  },
  "binding": [
   "min_pills",
   "glove_share"
  ],
  "slack": {
   "cornstarch": 710.0,
   "min_pills": 0.0,
   "glove_share": 0.0
  },
  "shadow_prices": null
 }
}
